export const RESERVED_WORKSPACE_SLUGS = [
  ...new Set([
    ...WORKSPACE_SLUG_RESERVED_LANDING_PREFIXES,
    ...WORKSPACE_SLUG_RESERVED_LANDING_EXACT_PATHS,
    ...APP_ROUTE_RESERVED_WORKSPACE_SLUGS,
    ...PRODUCT_ROUTE_RESERVED_WORKSPACE_SLUGS,
    ...ACCOUNT_ROUTE_RESERVED_WORKSPACE_SLUGS,
    ...MARKETING_ROUTE_RESERVED_WORKSPACE_SLUGS,
    ...INTEGRATION_ROUTE_RESERVED_WORKSPACE_SLUGS,
    ...PLATFORM_ROUTE_RESERVED_WORKSPACE_SLUGS,
    ...WELL_KNOWN_ROUTE_RESERVED_WORKSPACE_SLUGS,
    ...LOCALE_ROUTE_RESERVED_WORKSPACE_SLUGS,
  ]),
] as readonly string[];

const RESERVED_WORKSPACE_SLUG_SET = new Set<string>(RESERVED_WORKSPACE_SLUGS);

export function isReservedWorkspaceSlug(value: string): boolean {
  return RESERVED_WORKSPACE_SLUG_SET.has(value.trim().toLowerCase());
}
